package cn.yueji.balance;

import org.junit.Test;
import java.time.*;
import java.math.*;
import static org.junit.Assert.*;

public class V479RulesTest {
    TradingCalendar calendar(){TradingCalendar c=new TradingCalendar();c.addClosed(LocalDate.of(2026,10,1));c.addClosed(LocalDate.of(2026,10,2));return c;}
    Ledger.Data data(){Ledger.Data d=new Ledger.Data();Ledger.Account a=new Ledger.Account(1,"账户","银行");a.created=LocalDateTime.of(2026,1,1,0,0);a.opening=10000000;d.accounts.add(a);return d;}
    Ledger.Fund fund(Ledger.Data d,String code){Ledger.Fund f=new Ledger.Fund();f.id=d.nextId();f.code=code;f.name="测试"+code;f.plan.amount=10000;f.plan.accountId=1;f.plan.totalPeriods=10;d.funds.add(f);return f;}
    void price(Ledger.Fund f,int day,String value){f.prices.put(LocalDate.of(2026,10,day),new BigDecimal(value));f.nav=new BigDecimal(value);f.navDate="2026-10-"+day;}
    Ledger.FundBuy buy(Ledger.Data d,Ledger.Fund f){return addBuy(d,f,LocalDateTime.of(2026,10,19,10,0));}
    Ledger.FundBuy addBuy(Ledger.Data d,Ledger.Fund f,LocalDateTime at){Ledger.FundBuy b=new Ledger.FundBuy();b.id=d.nextId();b.at=at;b.amount=10000;f.buys.add(b);price(f,19,"1");FundEngine.resolve(f,calendar());return b;}
    @Test public void dailyBackfillsOnlyDueTradingDaysAndIsIdempotent(){Ledger.Data d=data();Ledger.Fund f=fund(d,"006431");TradingCalendar c=calendar();LocalDateTime through=LocalDateTime.of(2026,10,29,13,0);AutomaticInvestments.configure(f,"每日",1,LocalDateTime.of(2026,10,26,10,13),through,c);assertEquals(4,AutomaticInvestments.generate(d,f,through,c));assertEquals(LocalTime.of(10,13),f.buys.get(0).at.toLocalTime());assertEquals(LocalTime.NOON,f.buys.get(1).at.toLocalTime());assertEquals(0,AutomaticInvestments.generate(d,f,through,c));assertEquals(9960000,d.balance(d.accounts.get(0)));LedgerStore.validate(d);Ledger.Data restored=LedgerStore.decode(LedgerStore.encode(d));assertEquals(0,AutomaticInvestments.generate(restored,restored.funds.get(0),through,c));}
    @Test public void exactlyFifteenAndWeekendMoveToNextTradingDay(){Ledger.Data d=data();Ledger.Fund f=fund(d,"006431");AutomaticInvestments.configure(f,"每日",1,LocalDateTime.of(2026,10,23,15,0),LocalDateTime.of(2026,10,30,13,0),calendar());assertEquals("2026-10-26T12:00",f.plan.firstAt);f=fund(d,"006432");AutomaticInvestments.configure(f,"每日",1,LocalDateTime.of(2026,10,1,14,59),LocalDateTime.of(2026,10,30,13,0),calendar());assertEquals("2026-10-05T12:00",f.plan.firstAt);}
    @Test public void weeklyBiweeklyMonthlyStartStrictlyAfterConfiguration(){Ledger.Data d=data();Ledger.Fund f=fund(d,"006431");LocalDateTime thursday=LocalDateTime.of(2026,10,22,8,0);AutomaticInvestments.configure(f,"每周",3,null,thursday,calendar());assertEquals("2026-10-28T12:00",f.plan.nextAt);f.plan.frequency="每两周";AutomaticInvestments.advance(f.plan,LocalDateTime.parse(f.plan.nextAt),calendar());assertEquals("2026-11-11T12:00",f.plan.nextAt);AutomaticInvestments.configure(f,"每月",31,null,thursday,calendar());assertEquals("2026-11-02T12:00",f.plan.nextAt);AutomaticInvestments.advance(f.plan,LocalDateTime.parse(f.plan.nextAt),calendar());assertEquals("2026-11-30T12:00",f.plan.nextAt);}
    @Test public void appendBeforeLatestIsRejected(){Ledger.Data d=data();Ledger.Fund f=fund(d,"006431");addBuy(d,f,LocalDateTime.of(2026,10,28,13,0));try{AutomaticInvestments.configure(f,"每日",1,LocalDateTime.of(2026,10,26,12,0),FundEngine.now(),calendar());fail();}catch(IllegalArgumentException expected){}}
    @Test public void saleWaitsForNavThenKeepsCashUntilReceipt(){Ledger.Data d=data();Ledger.Fund f=fund(d,"006431");Ledger.FundBuy b=buy(d,f);Ledger.FundOrder o=FundSettlement.create(d,f,LocalDateTime.of(2026,10,23,10,0),1,"",10,1,3,calendar());assertFalse(FundSettlement.apply(d,LocalDateTime.of(2026,10,26,13,0),calendar()));assertNull(b.saleDate);price(f,23,"1.1");assertTrue(FundSettlement.apply(d,LocalDateTime.of(2026,10,26,13,0),calendar()));assertEquals(10990,b.saleAmount);assertEquals(LocalDate.of(2026,10,23),b.saleDate);assertEquals(10990,FundEngine.value(f,LocalDate.of(2026,10,27)));assertEquals(0,FundEngine.value(f,LocalDate.of(2026,10,29)));FundSettlement.apply(d,LocalDateTime.of(2026,10,29,13,0),calendar());assertEquals("已完成",o.status);LedgerStore.validate(d);}
    @Test public void conversionCreatesExactlyOneTargetBatchWithoutAccountCredit(){Ledger.Data d=data();Ledger.Fund f=fund(d,"006431"),target=fund(d,"006432");Ledger.FundBuy b=buy(d,f);price(f,23,"1.1");price(target,23,"2");Ledger.FundOrder o=FundSettlement.create(d,f,LocalDateTime.of(2026,10,23,10,0),0,target.code,0,1,1,calendar());FundSettlement.apply(d,LocalDateTime.of(2026,10,26,13,0),calendar());assertEquals(1,target.buys.size());assertEquals("转换",b.saleTag);assertEquals("转换",target.buys.get(0).transactionTag);assertEquals(new BigDecimal("55.00"),target.buys.get(0).units);FundSettlement.apply(d,LocalDateTime.of(2026,10,27,13,0),calendar());assertEquals(1,target.buys.size());assertFalse(b.saleAccountLinked);LedgerStore.validate(d);Ledger.Data copy=LedgerStore.decode(LedgerStore.encode(d));assertEquals(o.id,copy.fundOrders.get(0).id);assertEquals(o.targetBuyId,copy.fundOrders.get(0).targetBuyId);}
    @Test public void bankDailyReplacementRecalculatesWithoutDuplication(){Ledger.Data d=data();BankLedger.Draft draft=new BankLedger.Draft();draft.name="理财";draft.balance=100000L;draft.at=LocalDateTime.of(2026,10,20,10,0);BankLedger.Product p=BankLedger.apply(d,0,draft,false,null);BankAccounting.setDaily(d,p,LocalDate.of(2026,10,23),100);assertEquals(100,BankLedger.profit(p));assertEquals(100100,BankLedger.balance(p));BankAccounting.setDaily(d,p,LocalDate.of(2026,10,24),200);assertEquals(300,BankLedger.profit(p));BankAccounting.setDaily(d,p,LocalDate.of(2026,10,23),150);assertEquals(350,BankLedger.profit(p));assertEquals(100350,BankLedger.balance(p));assertNull(BankLedger.daily(p,LocalDate.of(2026,10,25)));LedgerStore.validate(d);}
    @Test public void currentWeekUsesOnlyConfirmedDailyEntriesNotLegacyWeeklyAmount(){Ledger.Data d=data();BankLedger.Draft draft=new BankLedger.Draft();draft.name="理财";draft.balance=100000L;draft.at=FundEngine.now().minusDays(10);BankLedger.Product p=BankLedger.apply(d,0,draft,false,null);LocalDate monday=BankLedger.monday(FundEngine.now().toLocalDate());assertNull(BankLedger.week(p,monday));p.observations.get(0).weekStart=monday;p.observations.get(0).weekly=99999L;assertNull(BankLedger.week(p,monday));p.observations.get(0).daily.put(monday,100L);p.observations.get(0).daily.put(monday.plusDays(1),-20L);assertEquals(Long.valueOf(80),BankLedger.week(p,monday));assertNull(BankLedger.daily(p,monday.plusDays(2)));}
    @Test public void multiBatchSaleAllocatesEveryCentOnce(){Ledger.Data d=data();Ledger.Fund f=fund(d,"006431");buy(d,f);addBuy(d,f,LocalDateTime.of(2026,10,19,11,0));price(f,23,"1.1111");Ledger.FundOrder o=FundSettlement.create(d,f,LocalDateTime.of(2026,10,23,10,0),1,"",13,1,3,calendar());FundSettlement.apply(d,LocalDateTime.of(2026,10,27,13,0),calendar());long sum=0;for(Ledger.FundBuy b:f.buys)sum+=b.saleAmount;assertEquals(22209,sum);assertEquals(sum,o.netAmount);assertTrue(f.buys.get(0).saleAmount<=o.netAmount);LedgerStore.validate(d);long before=d.balance(d.accounts.get(0));FundSettlement.apply(d,LocalDateTime.of(2026,10,29,13,0),calendar());LedgerStore.validate(d);assertEquals(before,d.balance(d.accounts.get(0)));}
    @Test public void insufficientAccountLeavesOnlyCommittedEarlierPeriodsAndCanResume(){Ledger.Data d=data();d.accounts.get(0).opening=15000;Ledger.Fund f=fund(d,"006431");AutomaticInvestments.configure(f,"每日",1,LocalDateTime.of(2026,10,26,12,0),LocalDateTime.of(2026,10,29,13,0),calendar());try{AutomaticInvestments.generate(d,f,LocalDateTime.of(2026,10,29,13,0),calendar());fail();}catch(IllegalArgumentException expected){}assertEquals(1,f.buys.size());assertEquals(1,f.plan.records.size());assertEquals("2026-10-27T12:00",f.plan.nextAt);assertEquals(5000,d.balance(d.accounts.get(0)));LedgerStore.validate(d);}
    @Test public void sameScheduleEditDoesNotReplayEarlierPurchases(){Ledger.Data d=data();Ledger.Fund f=fund(d,"006431");LocalDateTime first=LocalDateTime.of(2026,10,26,12,0),now=LocalDateTime.of(2026,10,29,13,0);AutomaticInvestments.configure(f,"每日",1,first,now,calendar());AutomaticInvestments.generate(d,f,now,calendar());String next=f.plan.nextAt;AutomaticInvestments.configure(f,"每日",1,first,now,calendar());assertEquals(next,f.plan.nextAt);assertEquals(0,AutomaticInvestments.generate(d,f,now,calendar()));}
    @Test public void missingTargetNavKeepsConversionMoneyAndCancelRestoresSource(){Ledger.Data d=data();Ledger.Fund source=fund(d,"006431"),target=fund(d,"006432");target.pendingOrder=true;Ledger.FundBuy original=buy(d,source);price(source,23,"1.1");Ledger.FundOrder order=FundSettlement.create(d,source,LocalDateTime.of(2026,10,23,10,0),0,target.code,0,1,1,calendar());FundSettlement.apply(d,LocalDateTime.of(2026,10,27,13,0),calendar());assertEquals(0,target.buys.size());assertTrue(original.releasePending);assertEquals(11000,FundEngine.value(source,LocalDate.of(2026,10,29)));FundSettlement.cancel(d,order.id);FundEngine.resolve(source,calendar());assertNull(original.saleDate);assertEquals(1,d.funds.size());assertTrue(d.fundOrders.isEmpty());LedgerStore.validate(d);}
}
